(1099039, 134630, 7291, '<td valign="top">Is that a lense baby or is this Photoshoped?</td>', 'Is that a lense baby or is this Photoshoped?', '2005-01-10 00:22:56.000000', NULL, 1),
(1099040, 134767, 24976, '<td valign="top">bokeh is not really a major part of this photo imo. its a good picture but maybe not for this challenge.</td>', 'bokeh is not really a major part of this photo imo. its a good picture but maybe not for this challenge.', '2005-01-10 00:23:12.000000', NULL, 1),
(1099056, 134485, 7291, '<td valign="top">Now this is exactly what I thought this challenge was all about.  Yes, there are some pictures with very nice and pleasing bokeh but this is the first one I see where the bokeh actually enhances the subject.  It''s actually framed but the bokeh.  Excellent job.</td>', 'Now this is exactly what I thought this challenge was all about.  Yes, there are some pictures with very nice and pleasing bokeh but this is the first one I see where the bokeh actually enhances the subject.  It''s actually framed but the bokeh.  Excellent job.', '2005-01-10 00:28:44.000000', NULL, 1),
(1099057, 134797, 27842, '<td valign="top">Beautiful color.</td>', 'Beautiful color.', '2005-01-10 00:28:48.000000', NULL, 1),
(1099059, 133660, 30857, '<td valign="top">Good bokeh, but also too many distractions on the background.</td>', 'Good bokeh, but also too many distractions on the background.', '2005-01-10 00:28:59.000000', NULL, 1),
(1099060, 134204, 7485, '<td valign="top">Superb idea! Somehow the photo looks like the ball is just pasted into a blurred image, but the idea is so good I''m giving it a 7 anyway.</td>', 'Superb idea! Somehow the photo looks like the ball is just pasted into a blurred image, but the idea is so good I''m giving it a 7 anyway.', '2005-01-10 00:29:22.000000', NULL, 1),
(1099073, 134056, 7291, '<td valign="top">Nice work with the post processing but it looks un-natural.</td>', 'Nice work with the post processing but it looks un-natural.', '2005-01-10 00:32:46.000000', NULL, 1),
(1099079, 134588, 7291, '<td valign="top">Outstanding!  I bet this looks amazing when printed.</td>', 'Outstanding!  I bet this looks amazing when printed.', '2005-01-10 00:34:26.000000', NULL, 1),
(1099084, 133759, 10658, '<td valign="top">That''s pretty cool!  This seems to work well for the challenge, in my opinion, and it''s an interesting shot even outside the challenge.</td>', 'That''s pretty cool!  This seems to work well for the challenge, in my opinion, and it''s an interesting shot even outside the challenge.', '2005-01-10 00:36:05.000000', NULL, 1),
(1099092, 134588, 255, '<td valign="top">now this is just plain cool. i love the vibrant colors--and even more so love the idea of viewing all the colored bulbs through a clear bulb.  perhps this is because i have a huge bag full of colored lightbulbs that i used to use for challenges--so the irony is not lost on me, i dont know. ;) at any rate, beautiful composition and clarity as well. is it good bokeh? beats the heck out of me. i just know i like it! nicely done.</td>', 'now this is just plain cool. i love the vibrant colors--and even more so love the idea of viewing all the colored bulbs through a clear bulb.  perhps this is because i have a huge bag full of colored lightbulbs that i used to use for challenges--so the irony is not lost on me, i dont know. ;) at any rate, beautiful composition and clarity as well. is it good bokeh? beats the heck out of me. i just know i like it! nicely done.', '2005-01-10 00:39:58.000000', NULL, 1),
(1099094, 134559, 27842, '<td valign="top">Interesting perspective</td>', 'Interesting perspective', '2005-01-10 00:40:46.000000', NULL, 1),
(1099097, 134716, 10658, '<td valign="top">For some reason I feel like I''ve seen this before.  Weird deja vu.  Anyway, good bokeh, love the bits of spiderweb that are highlighted and of course that weird spider is really something else.  Great capture!</td>', 'For some reason I feel like I''ve seen this before.  Weird deja vu.  Anyway, good bokeh, love the bits of spiderweb that are highlighted and of course that weird spider is really something else.  Great capture!', '2005-01-10 00:43:41.000000', NULL, 1),
(1099098, 134055, 27842, '<td valign="top">The background color works well with the subject.</td>', 'The background color works well with the subject.', '2005-01-10 00:43:58.000000', NULL, 1),
(1099099, 134723, 27842, '<td valign="top">He looks angry.  Nice capture.</td>', 'He looks angry.  Nice capture.', '2005-01-10 00:44:56.000000', NULL, 1),
