(1099241, 134372, 13749, '<td valign="top">not quite bokeh, but i venture that you''ve heard this before (or will be hearing it later).  in any other challenge, this may have worked well though.</td>', 'not quite bokeh, but i venture that you''ve heard this before (or will be hearing it later).  in any other challenge, this may have worked well though.', '2005-01-10 02:12:21.000000', NULL, 1),
