(1099244, 134682, 13749, '<td valign="top">not exactly bokeh =( - outside the context of the challenge though, this certainly has the potential to be a strong image</td>', 'not exactly bokeh =( - outside the context of the challenge though, this certainly has the potential to be a strong image', '2005-01-10 02:15:10.000000', NULL, 1),
(1099245, 133964, 13749, '<td valign="top">extremely beautiful.  the background really helps make this stand out.  great job.</td>', 'extremely beautiful.  the background really helps make this stand out.  great job.', '2005-01-10 02:15:52.000000', NULL, 1),
(1099251, 134632, 13749, '<td valign="top">wonderful shot.. i''m sure you''ll get grilled on whether or not this is actually bokeh, but i''ll just go ahead and leave it at my first comment.</td>', 'wonderful shot.. i''m sure you''ll get grilled on whether or not this is actually bokeh, but i''ll just go ahead and leave it at my first comment.', '2005-01-10 02:19:30.000000', NULL, 1),
(1099253, 134266, 19959, '<td valign="top">Nice idea. The strap is a little distracting and perhaps the lens glass would have been more aethetic that the lens cover for this photo.</td>', 'Nice idea. The strap is a little distracting and perhaps the lens glass would have been more aethetic that the lens cover for this photo.', '2005-01-10 02:19:47.000000', NULL, 1),
(1099257, 134614, 13749, '<td valign="top">lol - very funny shot!  i wonder how you set this up - did you just drop snowballs until you caught a good picture?  maybe not quite fitting to my understanding of ''bokeh'', but a good shot nonetheless</td>', 'lol - very funny shot!  i wonder how you set this up - did you just drop snowballs until you caught a good picture?  maybe not quite fitting to my understanding of ''bokeh'', but a good shot nonetheless', '2005-01-10 02:20:55.000000', NULL, 1),
(1099258, 134241, 19959, '<td valign="top">More soft-focus than Bokeh.</td>', 'More soft-focus than Bokeh.', '2005-01-10 02:20:56.000000', NULL, 1),
(1099259, 134336, 19959, '<td valign="top">Nice</td>', 'Nice', '2005-01-10 02:21:08.000000', NULL, 1),
(1099261, 134204, 13749, '<td valign="top">lol, very funny shot.  not sure that this will fit everyone''s definition of ''bokeh'', but a very creative and well-executed shot either way.</td>', 'lol, very funny shot.  not sure that this will fit everyone''s definition of ''bokeh'', but a very creative and well-executed shot either way.', '2005-01-10 02:22:11.000000', NULL, 1),
(1099265, 134563, 30861, '<td valign="top">A delicious, muted, subtle image where the interplay between background and subject is palpable but underplayed. IN my book, a very nice piece of work. May not be artefactual enough to satisfy most voters.</td>', 'A delicious, muted, subtle image where the interplay between background and subject is palpable but underplayed. IN my book, a very nice piece of work. May not be artefactual enough to satisfy most voters.', '2005-01-10 02:25:32.000000', NULL, 1),
(1099270, 134197, 30861, '<td valign="top">Wonderful image. Eeerie and cheerul at the same time. True Bokeh. Thumbs up!</td>', 'Wonderful image. Eeerie and cheerul at the same time. True Bokeh. Thumbs up!', '2005-01-10 02:27:53.000000', NULL, 1),
(1099272, 134802, 30861, '<td valign="top">Very sweet, unusual quality to the bokeh. Nice shot.</td>', 'Very sweet, unusual quality to the bokeh. Nice shot.', '2005-01-10 02:28:50.000000', NULL, 1),
(1099273, 134577, 30861, '<td valign="top">Knockout shot in many ways. I''m getting a little tired of droplets, frankly, but I''m not marking it down for that :-) Well done. True bokeh.</td>', 'Knockout shot in many ways. I''m getting a little tired of droplets, frankly, but I''m not marking it down for that :-) Well done. True bokeh.', '2005-01-10 02:30:00.000000', NULL, 1),
(1099274, 134806, 30861, '<td valign="top">Extraordinary artefacts. A very compelling image. True bokeh.</td>', 'Extraordinary artefacts. A very compelling image. True bokeh.', '2005-01-10 02:30:55.000000', NULL, 1),
(1099275, 134404, 30861, '<td valign="top">I love the mood of this, the down-key of it. I''d score it even higher if the bottom of the subject bud separated from the BG, which is one of the things I ask from bokeh.</td>', 'I love the mood of this, the down-key of it. I''d score it even higher if the bottom of the subject bud separated from the BG, which is one of the things I ask from bokeh.', '2005-01-10 02:31:59.000000', NULL, 1),
(1099277, 134675, 30861, '<td valign="top">Amusing take. Technically flawless. Wonderful sense of how to crop the image. True bokeh.</td>', 'Amusing take. Technically flawless. Wonderful sense of how to crop the image. True bokeh.', '2005-01-10 02:32:51.000000', NULL, 1),
(1099280, 134546, 30861, '<td valign="top">The only "people shot" in the challenge that shows true bokeh, IMO. Nice work. The eyes are marvelous.</td>', 'The only "people shot" in the challenge that shows true bokeh, IMO. Nice work. The eyes are marvelous.', '2005-01-10 02:34:16.000000', NULL, 1),
(1099281, 134451, 30861, '<td valign="top">The bokeh in this is very subtle; it''s hovering between shallow DOF and true bokeh IMO. Otherwise, a simply stunning image.</td>', 'The bokeh in this is very subtle; it''s hovering between shallow DOF and true bokeh IMO. Otherwise, a simply stunning image.', '2005-01-10 02:35:18.000000', NULL, 1),
(1099282, 134678, 30861, '<td valign="top">True bokeh. Very strong image marred, IMO, by the extreme hot spot in the center.</td>', 'True bokeh. Very strong image marred, IMO, by the extreme hot spot in the center.', '2005-01-10 02:36:20.000000', NULL, 1),
(1099285, 134808, 30861, '<td valign="top">True bokeh, but the background''s at war with the subject IMO. I''d like to see it with the BG blurred a little with gaussian and desatruated/decontrasted a bit. Even the face itself is a little too contrasty for my tatstes...</td>', 'True bokeh, but the background''s at war with the subject IMO. I''d like to see it with the BG blurred a little with gaussian and desatruated/decontrasted a bit. Even the face itself is a little too contrasty for my tatstes...', '2005-01-10 02:37:46.000000', NULL, 1),
