(1099541, 134546, 28299, '<td valign="top">Absolutely stunning - the clarity of your subject and the fantastic use of contrast and color. Beautifully soft shadowing also. You must live somewhere where it''s actually warm!</td>', 'Absolutely stunning - the clarity of your subject and the fantastic use of contrast and color. Beautifully soft shadowing also. You must live somewhere where it''s actually warm!', '2005-01-10 07:50:27.000000', NULL, 1),
(1099556, 134014, 3306, '<td valign="top">I don''t usually enjoy "toy" shots, but this one is special. Good job.</td>', 'I don''t usually enjoy "toy" shots, but this one is special. Good job.', '2005-01-10 08:06:51.000000', NULL, 1),
(1099568, 134808, 27812, '<td valign="top">I really want to be the first to say congratulations... this is a winner and definately a pic that will go into my favores list... 10</td>', 'I really want to be the first to say congratulations... this is a winner and definately a pic that will go into my favores list... 10', '2005-01-10 08:23:30.000000', NULL, 1),
