(1101030, 134491, 30214, '<td valign="top">excellent bokeh. A bit oversharpned foreground to my taste</td>', 'excellent bokeh. A bit oversharpned foreground to my taste', '2005-01-11 03:42:05.000000', NULL, 1),
(1101032, 134784, 31213, '<td valign="top">This picture lack a focal point.  Its all sort of blended and undefined.  Maybe if there was one specific focal point it may have worked better.....</td>', 'This picture lack a focal point.  Its all sort of blended and undefined.  Maybe if there was one specific focal point it may have worked better.....', '2005-01-11 03:43:25.000000', NULL, 1),
(1101035, 133480, 31213, '<td valign="top">Focus needs to be a bit sharper on their faces....also the out of focuss background is just that....not a great representation of bokeh as I''m sure you have realized from some of the other entries.  Priceless shot, but may not hold up! :(</td>', 'Focus needs to be a bit sharper on their faces....also the out of focuss background is just that....not a great representation of bokeh as I''m sure you have realized from some of the other entries.  Priceless shot, but may not hold up! :(', '2005-01-11 03:44:38.000000', NULL, 1),
(1101036, 134806, 31213, '<td valign="top">Little overboard.  Takes away from your subject.</td>', 'Little overboard.  Takes away from your subject.', '2005-01-11 03:45:51.000000', NULL, 1),
(1101037, 133272, 30214, '<td valign="top">interesting bokeh, nice colors</td>', 'interesting bokeh, nice colors', '2005-01-11 03:46:24.000000', NULL, 1),
(1101038, 134588, 30214, '<td valign="top">nice shot</td>', 'nice shot', '2005-01-11 03:46:40.000000', NULL, 1),
(1101040, 134505, 31213, '<td valign="top">Nice shot.  I with there was a little more of the picture in focus....either more of the dart or maybe from the bullseye to the left of the frame would have been more visually appealing.</td>', 'Nice shot.  I with there was a little more of the picture in focus....either more of the dart or maybe from the bullseye to the left of the frame would have been more visually appealing.', '2005-01-11 03:48:01.000000', NULL, 1),
(1101041, 134246, 31213, '<td valign="top">Nice job!  I think some of the white bokeh hides some of the blown out portions of your subject....little distracting there, but otherwise very nicely done.</td>', 'Nice job!  I think some of the white bokeh hides some of the blown out portions of your subject....little distracting there, but otherwise very nicely done.', '2005-01-11 03:48:54.000000', NULL, 1),
