(1101043, 133839, 31213, '<td valign="top">Cute kid, but doesn''t meet the challenge.  Perhaps if you were closer to your subject, and used a larger aperature those books would have been converted from slightly out of focus to bokeh.</td>', 'Cute kid, but doesn''t meet the challenge.  Perhaps if you were closer to your subject, and used a larger aperature those books would have been converted from slightly out of focus to bokeh.', '2005-01-11 03:50:22.000000', NULL, 1),
(1101044, 134404, 30214, '<td valign="top">excellent, my favorite so far</td>', 'excellent, my favorite so far', '2005-01-11 03:52:28.000000', NULL, 1),
(1101046, 133660, 31213, '<td valign="top">Background bokeh does not enhance your subject.  This is a quote from the description of the challenge, "take a photograph whose subject is enhanced by the bokeh of the background."  I don''t feel that the house enhances your turtle....the shapes and color and overal feel of the background does nothing for your actual subject.  Nice try.</td>', 'Background bokeh does not enhance your subject.  This is a quote from the description of the challenge, "take a photograph whose subject is enhanced by the bokeh of the background."  I don''t feel that the house enhances your turtle....the shapes and color and overal feel of the background does nothing for your actual subject.  Nice try.', '2005-01-11 03:52:43.000000', NULL, 1),
(1101047, 134733, 30214, '<td valign="top">grea shot</td>', 'grea shot', '2005-01-11 03:52:44.000000', NULL, 1),
(1101048, 134813, 31213, '<td valign="top">Wisht the background was a little more out of focus.  It''s sharp enough now to distract my eye from your subject.</td>', 'Wisht the background was a little more out of focus.  It''s sharp enough now to distract my eye from your subject.', '2005-01-11 03:53:17.000000', NULL, 1),
