(1101050, 134815, 31213, '<td valign="top">Nice job capturing the bokeh.  It would have been a little better if she wore a different color hat so there was more contrast between her and the background.  Nice shot though.</td>', 'Nice job capturing the bokeh.  It would have been a little better if she wore a different color hat so there was more contrast between her and the background.  Nice shot though.', '2005-01-11 03:54:41.000000', NULL, 1),
(1101051, 133846, 31213, '<td valign="top">Background blur is a little too smooth....like creamy peanut butter.  This is good in the sense that it doesn''t distract us from your subject.....but bad in the sense that the challenge asks us to, "take a photograph whose subject is enhanced by the bokeh of the background."</td>', 'Background blur is a little too smooth....like creamy peanut butter.  This is good in the sense that it doesn''t distract us from your subject.....but bad in the sense that the challenge asks us to, "take a photograph whose subject is enhanced by the bokeh of the background."', '2005-01-11 03:57:02.000000', NULL, 1),
(1101054, 134732, 31213, '<td valign="top">One of the best yet.....You may have a ribbon here....goodluck!</td>', 'One of the best yet.....You may have a ribbon here....goodluck!', '2005-01-11 03:59:21.000000', NULL, 1),
