(1109368, 133120, 1024, '<td valign="top">I love the composition of this shot, and old barns are one of my favorite subjects</td>', 'I love the composition of this shot, and old barns are one of my favorite subjects', '2005-01-15 18:48:19.000000', NULL, 1),
(1109372, 134679, 18838, '<td valign="top">very lovely colors!!</td>', 'very lovely colors!!', '2005-01-15 18:49:19.000000', NULL, 1),
(1109373, 134807, 1024, '<td valign="top">I really like this photo on many levels.... bokeh, composition, lighting, all excellent</td>', 'I really like this photo on many levels.... bokeh, composition, lighting, all excellent', '2005-01-15 18:50:28.000000', NULL, 1),
(1109374, 134805, 18838, '<td valign="top">cool idea</td>', 'cool idea', '2005-01-15 18:50:57.000000', NULL, 1),
(1109378, 133948, 30625, '<td valign="top">Great Composition, Good effect with the light sources, I love how you can see the texture of the wood grains. (8)</td>', 'Great Composition, Good effect with the light sources, I love how you can see the texture of the wood grains. (8)', '2005-01-15 18:54:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1109382, 133388, 30625, '<td valign="top">Bravo Bokeh....I see the round light circles gleaming the flower/plant definition. This is a Bokeh technique shot. Well done (9)</td>', 'Bravo Bokeh....I see the round light circles gleaming the flower/plant definition. This is a Bokeh technique shot. Well done (9)', '2005-01-15 18:58:15.000000', NULL, 1),
(1109385, 134146, 18838, '<td valign="top">why is the glass empty???</td>', 'why is the glass empty???', '2005-01-15 18:59:28.000000', NULL, 1),
(1109388, 134283, 30625, '<td valign="top">I think a little more on the background would have made this a spectacular shot. The background is to bland just needed something a little in contrast to throw the flower at you more. (7)</td>', 'I think a little more on the background would have made this a spectacular shot. The background is to bland just needed something a little in contrast to throw the flower at you more. (7)', '2005-01-15 19:00:33.000000', NULL, 1),
(1109398, 134687, 18838, '<td valign="top">image seems very dark to me ... white on the bottle sticker is only 50% grey ... and focus on the wrong subject ;-)</td>', 'image seems very dark to me ... white on the bottle sticker is only 50% grey ... and focus on the wrong subject ;-)', '2005-01-15 19:04:38.000000', NULL, 1),
(1109402, 134172, 12160, '<td valign="top">Beautiful colors and softness. Very nice. 8</td>', 'Beautiful colors and softness. Very nice. 8', '2005-01-15 19:06:33.000000', NULL, 1),
(1109403, 134775, 18838, '<td valign="top">fits bokeh very well ... the background looks almost impressionistic to me</td>', 'fits bokeh very well ... the background looks almost impressionistic to me', '2005-01-15 19:06:45.000000', NULL, 1),
(1109404, 134732, 18838, '<td valign="top">very zen ;-)</td>', 'very zen ;-)', '2005-01-15 19:07:23.000000', NULL, 1),
(1109459, 134546, 15204, '<td valign="top">Very nice portrait.  The lighting on the face is very good.  I think it would look even better with a little cropped off the right side.  I like the angles and the pose.</td>', 'Very nice portrait.  The lighting on the face is very good.  I think it would look even better with a little cropped off the right side.  I like the angles and the pose.', '2005-01-15 20:00:23.000000', NULL, 1),
(1109470, 134283, 15204, '<td valign="top">Beautiful bokeh and well done on the whites. -8</td>', 'Beautiful bokeh and well done on the whites. -8', '2005-01-15 20:05:24.000000', NULL, 1),
(1109491, 134734, 17890, '<td valign="top">My favourite in this challenge - great bokeh - wonderful touching expression from ''Betty'' - clear and sharp subject with great great color in background - 10</td>', 'My favourite in this challenge - great bokeh - wonderful touching expression from ''Betty'' - clear and sharp subject with great great color in background - 10', '2005-01-15 20:22:43.000000', NULL, 1),
(1109494, 134704, 17890, '<td valign="top">I love this photo - good bokeh - very sharp and clear - 10</td>', 'I love this photo - good bokeh - very sharp and clear - 10', '2005-01-15 20:25:59.000000', NULL, 1),
(1109504, 134805, 25397, '<td valign="top">Awesome, reminds me of that one picture for the matrix challenge.</td>', 'Awesome, reminds me of that one picture for the matrix challenge.', '2005-01-15 20:38:39.000000', NULL, 1),
(1109529, 134605, 30392, '<td valign="top">this HAS to win blue...</td>', 'this HAS to win blue...', '2005-01-15 21:11:15.000000', NULL, 1),
(1109530, 134816, 30392, '<td valign="top">sorry, but everything is bokeh, nothing''s in focus!</td>', 'sorry, but everything is bokeh, nothing''s in focus!', '2005-01-15 21:13:04.000000', NULL, 1),
(1109599, 134485, 21724, '<td valign="top">I LOVE this shot.  I think it might work a bit better if the dart were more off center, although I do like the symmetry of it as-is.  You did a great job of getting the colored bars to perfectly aligned.  If this one doesn''t place highly, it''s a crime!</td>', 'I LOVE this shot.  I think it might work a bit better if the dart were more off center, although I do like the symmetry of it as-is.  You did a great job of getting the colored bars to perfectly aligned.  If this one doesn''t place highly, it''s a crime!', '2005-01-15 22:21:30.000000', NULL, 1),
(1109600, 134803, 21724, '<td valign="top">great use of rule-of-thirds!  nice title, too</td>', 'great use of rule-of-thirds!  nice title, too', '2005-01-15 22:21:54.000000', NULL, 1),
(1109601, 134678, 21724, '<td valign="top">beautiful colors, LOVE this shot!!  marking it as a favorite!</td>', 'beautiful colors, LOVE this shot!!  marking it as a favorite!', '2005-01-15 22:22:22.000000', NULL, 1),
(1109602, 134146, 21724, '<td valign="top">definitely looks like an advertisement... I wish the lighting were a little better on the bottle so the label wasn''t so hard to see, but at least the colors fit in well with the background.  very nice shot, love it!</td>', 'definitely looks like an advertisement... I wish the lighting were a little better on the bottle so the label wasn''t so hard to see, but at least the colors fit in well with the background.  very nice shot, love it!', '2005-01-15 22:24:21.000000', NULL, 1),
(1109604, 134644, 21724, '<td valign="top">great composition, much different from the usual chess piece shots!</td>', 'great composition, much different from the usual chess piece shots!', '2005-01-15 22:24:44.000000', NULL, 1),
(1109605, 133920, 21724, '<td valign="top">I think that it''s more the colors of this shot that set the foreground apart, as opposed to the focusing.  a good general flower shot, but not necessarily fit for this challenge</td>', 'I think that it''s more the colors of this shot that set the foreground apart, as opposed to the focusing.  a good general flower shot, but not necessarily fit for this challenge', '2005-01-15 22:26:00.000000', NULL, 1),
(1109606, 134576, 21724, '<td valign="top">good shot, but there''s nothing that''s reeeeally out of focus to accentuatethe foreground.  not right for this challenge, sorry :(</td>', 'good shot, but there''s nothing that''s reeeeally out of focus to accentuatethe foreground.  not right for this challenge, sorry :(', '2005-01-15 22:30:54.000000', NULL, 1),
(1109608, 134822, 21724, '<td valign="top">appropriate for the challenge, but no "wow" factor to make it a winner.  good use of bokeh, though!</td>', 'appropriate for the challenge, but no "wow" factor to make it a winner.  good use of bokeh, though!', '2005-01-15 22:31:27.000000', NULL, 1),
(1109609, 133090, 21724, '<td valign="top">nice use of framing, composition, and bokeh!  seems a little noisy, though.. I wonder what ISO you used..</td>', 'nice use of framing, composition, and bokeh!  seems a little noisy, though.. I wonder what ISO you used..', '2005-01-15 22:33:22.000000', NULL, 1),
(1109611, 134559, 21724, '<td valign="top">that is one HUGE paw!!  I would have used a white background instead of the patterned one you used, just to make it seem more professional.  would have been cool to see the animal''s face out of focus in the background, too</td>', 'that is one HUGE paw!!  I would have used a white background instead of the patterned one you used, just to make it seem more professional.  would have been cool to see the animal''s face out of focus in the background, too', '2005-01-15 22:35:18.000000', NULL, 1),
(1109613, 133891, 21724, '<td valign="top">interesting subject!!  what a cool find!</td>', 'interesting subject!!  what a cool find!', '2005-01-15 22:35:55.000000', NULL, 1),
(1109616, 134609, 21724, '<td valign="top">*rimshot* AAAAAAHAAHAHHAHAH.. cute ;)</td>', '*rimshot* AAAAAAHAAHAHHAHAH.. cute ;)', '2005-01-15 22:37:07.000000', NULL, 1),
(1109618, 134701, 21724, '<td valign="top">love it!!  there''s something about the look of this one.. the colors and contrast really pop on it.. it makes something otherwise boring seem way more interesting.  great job!</td>', 'love it!!  there''s something about the look of this one.. the colors and contrast really pop on it.. it makes something otherwise boring seem way more interesting.  great job!', '2005-01-15 22:37:51.000000', NULL, 1),
(1109623, 134812, 21724, '<td valign="top">the drop of water doesn''t really seem in focus.. could get sharper</td>', 'the drop of water doesn''t really seem in focus.. could get sharper', '2005-01-15 22:38:48.000000', NULL, 1),
(1109634, 134811, 21724, '<td valign="top">I don''t understand how this fits bokeh.. the only thing out of focus is the upper left corner, and it doesn''t really add to the picture at all.. good pic, but not fit for this challenge</td>', 'I don''t understand how this fits bokeh.. the only thing out of focus is the upper left corner, and it doesn''t really add to the picture at all.. good pic, but not fit for this challenge', '2005-01-15 22:44:22.000000', NULL, 1),
(1109636, 134721, 21724, '<td valign="top">cool background!!</td>', 'cool background!!', '2005-01-15 22:45:10.000000', NULL, 1),
(1109638, 134806, 21724, '<td valign="top">my favorite for the challenge</td>', 'my favorite for the challenge', '2005-01-15 22:46:57.000000', NULL, 1),
(1109641, 134605, 21724, '<td valign="top">i don''t think that this photo is good, but I think it''s the content that makes it good, not the bokeh</td>', 'i don''t think that this photo is good, but I think it''s the content that makes it good, not the bokeh', '2005-01-15 22:50:29.000000', NULL, 1),
(1109661, 134704, 16912, '<td valign="top">Magnificent shot!  It has a winters morning look, positioning of the bird is great I just wish I could see his eye. a shot I''d be proud to take.</td>', 'Magnificent shot!  It has a winters morning look, positioning of the bird is great I just wish I could see his eye. a shot I''d be proud to take.', '2005-01-15 23:04:45.000000', NULL, 1),
