(1109682, 134635, 24674, '<td valign="top">Nice portrait, but I am not sure it is helped by the bokeh.</td>', 'Nice portrait, but I am not sure it is helped by the bokeh.', '2005-01-15 23:15:30.000000', NULL, 1),
(1109683, 134704, 1827, '<td valign="top">Very nice indeed.  The framing is terrific, and I love the level of detail you managed to capture.  The background really accentuates the downy softness of the feathers.  Great work.  I hope to see you ribbon.</td>', 'Very nice indeed.  The framing is terrific, and I love the level of detail you managed to capture.  The background really accentuates the downy softness of the feathers.  Great work.  I hope to see you ribbon.', '2005-01-15 23:15:49.000000', NULL, 1),
(1109690, 134734, 1827, '<td valign="top">Fabulous the way you managed to match the background to his coloring so well.  My only complaint is that he feels a bit chopped off at the neck, I''d have preferred to have more of his body in the shot.  He is a gorgeous dog.  And my apologies if he''s a she.</td>', 'Fabulous the way you managed to match the background to his coloring so well.  My only complaint is that he feels a bit chopped off at the neck, I''d have preferred to have more of his body in the shot.  He is a gorgeous dog.  And my apologies if he''s a she.', '2005-01-15 23:17:23.000000', NULL, 1),
(1109693, 134804, 1827, '<td valign="top">Very creative.  This photo exceeds the challenge requirements: while the bokeh does add interest to the photo, this goes one further by providing interest in what would otherwise be an uninteresting photo.  Taking the mundane and making it interesting is a skill indeed.  Good job. 8</td>', 'Very creative.  This photo exceeds the challenge requirements: while the bokeh does add interest to the photo, this goes one further by providing interest in what would otherwise be an uninteresting photo.  Taking the mundane and making it interesting is a skill indeed.  Good job. 8', '2005-01-15 23:19:38.000000', NULL, 1),
(1109700, 134003, 12253, '<td valign="top">This is excellent; nice composition and a great shot.  One of my top pics for the challenge.  10 from me!</td>', 'This is excellent; nice composition and a great shot.  One of my top pics for the challenge.  10 from me!', '2005-01-15 23:25:03.000000', NULL, 1),
(1109703, 134732, 12253, '<td valign="top">Beautiful silky smooth bokeh, and a really great looking drop!  Well captured with good light.  Bumping up!</td>', 'Beautiful silky smooth bokeh, and a really great looking drop!  Well captured with good light.  Bumping up!', '2005-01-15 23:25:45.000000', NULL, 1),
(1109718, 134145, 32147, '<td valign="top">as a musician and photographer, I find this photo appealing on many levels.<br/>Great use of color and good control of DOF.  nice job.</td>', 'as a musician and photographer, I find this photo appealing on many levels.Great use of color and good control of DOF.  nice job.', '2005-01-15 23:45:21.000000', NULL, 1),
(1109720, 134723, 23456, '<td valign="top">It''s almost like - How dare you take a photo of me !! Nice sharp capture !</td>', 'It''s almost like - How dare you take a photo of me !! Nice sharp capture !', '2005-01-15 23:47:43.000000', NULL, 1),
(1109722, 134577, 32147, '<td valign="top">Excellent Shot.  I like the balance here.  Great use of multiple colors.</td>', 'Excellent Shot.  I like the balance here.  Great use of multiple colors.', '2005-01-15 23:47:54.000000', NULL, 1),
(1109724, 134197, 23456, '<td valign="top">effective</td>', 'effective', '2005-01-15 23:49:34.000000', NULL, 1),
(1109731, 134301, 23456, '<td valign="top">Bokeh takes up the majority of this photo unfortunately. If more of the pine cone ends were in focus it would have been more appealing shot.</td>', 'Bokeh takes up the majority of this photo unfortunately. If more of the pine cone ends were in focus it would have been more appealing shot.', '2005-01-15 23:56:43.000000', NULL, 1),
