(1109747, 133109, 23456, '<td valign="top">simple and appealing. Well done !</td>', 'simple and appealing. Well done !', '2005-01-16 00:02:57.000000', NULL, 1),
(1109787, 134546, 23456, '<td valign="top">nice well done !</td>', 'nice well done !', '2005-01-16 00:11:41.000000', NULL, 1),
(1109820, 134461, 12809, '<td valign="top">Nice bokeh but the subject isn''t as sharp as it should be.</td>', 'Nice bokeh but the subject isn''t as sharp as it should be.', '2005-01-16 00:16:48.000000', NULL, 1),
(1109824, 134644, 12809, '<td valign="top">A little too much negative space at the top for me.  Good bokeh though.</td>', 'A little too much negative space at the top for me.  Good bokeh though.', '2005-01-16 00:17:18.000000', NULL, 1),
(1109832, 133759, 12809, '<td valign="top">Interesting take on the idea.  Good colors.  Seems to be a bit oversharpened.</td>', 'Interesting take on the idea.  Good colors.  Seems to be a bit oversharpened.', '2005-01-16 00:18:13.000000', NULL, 1),
