(1109865, 134812, 12809, '<td valign="top">Good focus on the droplet.  I like the colors.  Very soothing.</td>', 'Good focus on the droplet.  I like the colors.  Very soothing.', '2005-01-16 00:21:35.000000', NULL, 1),
(1109868, 134485, 12809, '<td valign="top">Good focus and shallow dof.  Nice bokeh.</td>', 'Good focus and shallow dof.  Nice bokeh.', '2005-01-16 00:21:54.000000', NULL, 1),
(1109876, 134775, 12809, '<td valign="top">One of my faves from the bunch.  I know people get tired of flowers but this is a good shot with excellent bokeh.  The bee (sharp bee) adds an interesting element to the shot.  Well done.</td>', 'One of my faves from the bunch.  I know people get tired of flowers but this is a good shot with excellent bokeh.  The bee (sharp bee) adds an interesting element to the shot.  Well done.', '2005-01-16 00:22:43.000000', NULL, 1),
(1109885, 134588, 12809, '<td valign="top">A unique shot out of the bunch.  The bright colors and shapes are great.  Adding the lightbulb to distort and add texture to the ''dots'' really makes this good.  Nice job.</td>', 'A unique shot out of the bunch.  The bright colors and shapes are great.  Adding the lightbulb to distort and add texture to the ''dots'' really makes this good.  Nice job.', '2005-01-16 00:24:03.000000', NULL, 1),
(1109897, 134605, 12809, '<td valign="top">Great use of dof.  Left just enough in focus for us to make out the yes.  Nice choice for b&amp;w.</td>', 'Great use of dof.  Left just enough in focus for us to make out the yes.  Nice choice for b&w.', '2005-01-16 00:25:04.000000', NULL, 1),
(1109899, 134577, 12809, '<td valign="top">Bright and cheery.  Nice ''drop''!</td>', 'Bright and cheery.  Nice ''drop''!', '2005-01-16 00:25:20.000000', NULL, 1),
(1109903, 134732, 12809, '<td valign="top">I like the simplicity of this.  Really pretty looking drop.</td>', 'I like the simplicity of this.  Really pretty looking drop.', '2005-01-16 00:25:46.000000', NULL, 1),
(1109915, 133090, 12809, '<td valign="top">One of the few who chose to (imo) blur the subject.  I like it.  Nice job of framing.  Good bokeh.</td>', 'One of the few who chose to (imo) blur the subject.  I like it.  Nice job of framing.  Good bokeh.', '2005-01-16 00:26:29.000000', NULL, 1),
(1109927, 134796, 12809, '<td valign="top">Probably my favorite of the bunch.  Some people may think it''s too "ordinary" to score it high but it''s a very well shot image with good lighting and bokeh.  This would make a beautiful holiday card.<br/> <br/>9</td>', 'Probably my favorite of the bunch.  Some people may think it''s too "ordinary" to score it high but it''s a very well shot image with good lighting and bokeh.  This would make a beautiful holiday card. 9', '2005-01-16 00:27:52.000000', NULL, 1),
