(1112846, 134668, 31559, '<td valign="top">excellent</td>', 'excellent', '2005-01-16 21:47:57.000000', NULL, 1),
(1112847, 134508, 17507, '<td valign="top">Background is a bit confusing, and too close in tonal range to the foreground. Kind of hard to distinguish the shot glasses that are in focus from the blurred background.</td>', 'Background is a bit confusing, and too close in tonal range to the foreground. Kind of hard to distinguish the shot glasses that are in focus from the blurred background.', '2005-01-16 21:47:59.000000', NULL, 1),
(1112849, 134575, 17507, '<td valign="top">Nice split-complement color palette :)</td>', 'Nice split-complement color palette :)', '2005-01-16 21:48:29.000000', NULL, 1),
(1112850, 134604, 31559, '<td valign="top">Very good work. Nice. I like the colors behind.</td>', 'Very good work. Nice. I like the colors behind.', '2005-01-16 21:48:44.000000', NULL, 1),
(1112853, 134732, 17507, '<td valign="top">Wow. that''s killer! The bokeh is not particularly striking, but as an example of shallow DOF, it''s entirely amazing. Nice muted color palette; good smooth lines. Wouldn''t be surprised to see this place; almost expect it to be in the top 10.</td>', 'Wow. that''s killer! The bokeh is not particularly striking, but as an example of shallow DOF, it''s entirely amazing. Nice muted color palette; good smooth lines. Wouldn''t be surprised to see this place; almost expect it to be in the top 10.', '2005-01-16 21:50:21.000000', NULL, 1),
(1112856, 134646, 31559, '<td valign="top">Excellent picture. Original and nice. Good work</td>', 'Excellent picture. Original and nice. Good work', '2005-01-16 21:51:05.000000', NULL, 1),
(1112860, 134691, 31559, '<td valign="top">Too strong the behind color. Otherwise nice</td>', 'Too strong the behind color. Otherwise nice', '2005-01-16 21:52:31.000000', NULL, 1),
(1112876, 134476, 31559, '<td valign="top">Beautifull. You could make it better with a little more light in front.</td>', 'Beautifull. You could make it better with a little more light in front.', '2005-01-16 21:57:03.000000', NULL, 1),
(1112877, 134734, 7969, '<td valign="top">very nice shot, tho i think a tighter crop on top would of improved this shot a lot,</td>', 'very nice shot, tho i think a tighter crop on top would of improved this shot a lot,', '2005-01-16 21:57:35.000000', NULL, 1),
(1112880, 134456, 31559, '<td valign="top">Beautifull.</td>', 'Beautifull.', '2005-01-16 21:58:02.000000', NULL, 1),
(1112889, 134684, 31559, '<td valign="top">Nice. Better without the light on the snow.</td>', 'Nice. Better without the light on the snow.', '2005-01-16 22:00:57.000000', NULL, 1),
(1112890, 134803, 7969, '<td valign="top">I like the risque composition of this shot, obviously deliberate.  Background certainly adds a degree of ominous-ness (i know not a word) to this already dark and brooding creature.  Your rendering captures the darkness of the crow and his reputation for being a kind of ''bad guy''. <br/>I also like the texture on his beak and light in his eye.  By the way how can you tell the male from female crow?</td>', 'I like the risque composition of this shot, obviously deliberate.  Background certainly adds a degree of ominous-ness (i know not a word) to this already dark and brooding creature.  Your rendering captures the darkness of the crow and his reputation for being a kind of ''bad guy''. I also like the texture on his beak and light in his eye.  By the way how can you tell the male from female crow?', '2005-01-16 22:01:31.000000', NULL, 1),
(1112896, 133674, 7969, '<td valign="top">I really like this cow.  He has an emotive expression.  I do wish you had cropped out the crooked horizon line, helping the eye to be focused on the subject.  I do like the blur of the barbed wire in the front and back nice use of DOF.  I also like the 3 blurred cows on the right. pulls your eye in a diagonal way.</td>', 'I really like this cow.  He has an emotive expression.  I do wish you had cropped out the crooked horizon line, helping the eye to be focused on the subject.  I do like the blur of the barbed wire in the front and back nice use of DOF.  I also like the 3 blurred cows on the right. pulls your eye in a diagonal way.', '2005-01-16 22:04:19.000000', NULL, 1),
(1112897, 134404, 31559, '<td valign="top">Beautiful. Excellent composition.</td>', 'Beautiful. Excellent composition.', '2005-01-16 22:04:46.000000', NULL, 1),
(1112903, 134003, 7969, '<td valign="top">Beautiful and simple line very nice DOF, lovely color tones. Lovely. Nice diagonal line too</td>', 'Beautiful and simple line very nice DOF, lovely color tones. Lovely. Nice diagonal line too', '2005-01-16 22:06:42.000000', NULL, 1),
(1112904, 134758, 13772, '<td valign="top">This is just an amazing capture of geese. I love it. Great work!</td>', 'This is just an amazing capture of geese. I love it. Great work!', '2005-01-16 22:07:16.000000', NULL, 1),
(1112905, 134806, 10985, '<td valign="top">Original bg and very interesting composition. Great toning, too.</td>', 'Original bg and very interesting composition. Great toning, too.', '2005-01-16 22:07:24.000000', NULL, 1),
(1112908, 134491, 10985, '<td valign="top">The bokeh is perfect and the light is beautifull. I might have composed differently, not so centered.</td>', 'The bokeh is perfect and the light is beautifull. I might have composed differently, not so centered.', '2005-01-16 22:08:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1112909, 133849, 10985, '<td valign="top">Fresh, delicate, appealing.</td>', 'Fresh, delicate, appealing.', '2005-01-16 22:08:49.000000', NULL, 1),
(1112912, 134815, 10985, '<td valign="top">If she finds it fun, don''t try to stop her!  ;o)  Fun and happy shot.</td>', 'If she finds it fun, don''t try to stop her!  ;o)  Fun and happy shot.', '2005-01-16 22:09:44.000000', NULL, 1),
(1112915, 134510, 10985, '<td valign="top">Poetic!</td>', 'Poetic!', '2005-01-16 22:09:54.000000', NULL, 1),
(1112919, 133405, 10985, '<td valign="top">Crisp selective focus and colors. Nicely composed and presented.</td>', 'Crisp selective focus and colors. Nicely composed and presented.', '2005-01-16 22:10:58.000000', NULL, 1),
(1112921, 134017, 10985, '<td valign="top">Cool presentation!</td>', 'Cool presentation!', '2005-01-16 22:11:35.000000', NULL, 1),
(1112926, 134786, 10985, '<td valign="top">Effective! A complete statue may have had even more impact. Not sure. I like the extra-sharp detail on the statue.</td>', 'Effective! A complete statue may have had even more impact. Not sure. I like the extra-sharp detail on the statue.', '2005-01-16 22:12:56.000000', NULL, 1),
(1112929, 133982, 13772, '<td valign="top">Actually prickly pear fruit. You knew that!  I think the bukeh in this one is just right. Nice capture and good work. Can''t wait to see who took this one. Good luck!</td>', 'Actually prickly pear fruit. You knew that!  I think the bukeh in this one is just right. Nice capture and good work. Can''t wait to see who took this one. Good luck!', '2005-01-16 22:13:26.000000', NULL, 1),
(1112931, 134723, 10985, '<td valign="top">Powerful looka and composition. The bokeh here makes it althemore impressive!</td>', 'Powerful looka and composition. The bokeh here makes it althemore impressive!', '2005-01-16 22:14:59.000000', NULL, 1),
(1112932, 134732, 7560, '<td valign="top">Probably the best example of bokeh in the challenge. Excellent composition, captivating subject. Oh yeah, and nice bokeh. ;) 10</td>', 'Probably the best example of bokeh in the challenge. Excellent composition, captivating subject. Oh yeah, and nice bokeh. ;) 10', '2005-01-16 22:15:29.000000', NULL, 1),
(1112933, 134495, 10985, '<td valign="top">Delicate. Lovely.</td>', 'Delicate. Lovely.', '2005-01-16 22:15:42.000000', NULL, 1),
(1112934, 134679, 10985, '<td valign="top">Cool colors and light.</td>', 'Cool colors and light.', '2005-01-16 22:16:13.000000', NULL, 1),
(1112935, 133649, 7560, '<td valign="top">An incredibly imaginative shot. Perfect example of how bokeh can truly enhance a shot, and nice in that this is not what you think of as a typical bokeh shot either. Might be kinda fun to crop it a bit and give it a 180 turn. Just to see. 10</td>', 'An incredibly imaginative shot. Perfect example of how bokeh can truly enhance a shot, and nice in that this is not what you think of as a typical bokeh shot either. Might be kinda fun to crop it a bit and give it a 180 turn. Just to see. 10', '2005-01-16 22:17:00.000000', NULL, 1),
(1112936, 134704, 10985, '<td valign="top">Must have been difficult to catch, they''re so small and swift! Sweet and perfectly composed.</td>', 'Must have been difficult to catch, they''re so small and swift! Sweet and perfectly composed.', '2005-01-16 22:17:24.000000', NULL, 1),
(1112937, 133920, 31559, '<td valign="top">Beautiful. I like the natural composition of colors and contrast with behind. Very good work. Congratulations. Have my ten.</td>', 'Beautiful. I like the natural composition of colors and contrast with behind. Very good work. Congratulations. Have my ten.', '2005-01-16 22:17:49.000000', NULL, 1),
(1112941, 133982, 31559, '<td valign="top">Beautiful. Nice composition</td>', 'Beautiful. Nice composition', '2005-01-16 22:18:42.000000', NULL, 1),
(1112943, 134295, 7560, '<td valign="top">This is a beautiful shot. I love the lighting and composition. There is what looks to be a back branch that is blurred out, but has just enough of a line to it still to distract me. That''s the only element that keeps this from being a 10. One of my faves from the challenge overall. Very well done. 9</td>', 'This is a beautiful shot. I love the lighting and composition. There is what looks to be a back branch that is blurred out, but has just enough of a line to it still to distract me. That''s the only element that keeps this from being a 10. One of my faves from the challenge overall. Very well done. 9', '2005-01-16 22:19:38.000000', NULL, 1),
(1112944, 134491, 31559, '<td valign="top">Beautiful. Excellent work. I like it very much.</td>', 'Beautiful. Excellent work. I like it very much.', '2005-01-16 22:20:20.000000', NULL, 1),
(1112947, 134733, 7560, '<td valign="top">A classic example of nice bokeh. I love the snow here and thing it really adds to the beauty.</td>', 'A classic example of nice bokeh. I love the snow here and thing it really adds to the beauty.', '2005-01-16 22:20:46.000000', NULL, 1),
(1112953, 134803, 7560, '<td valign="top">Excellent bokeh, but the raven is a little hot. I''m looking forward to seeing what was behind the raven when I read your notes. 8</td>', 'Excellent bokeh, but the raven is a little hot. I''m looking forward to seeing what was behind the raven when I read your notes. 8', '2005-01-16 22:21:57.000000', NULL, 1),
(1112955, 134703, 31559, '<td valign="top">Very nice. Excellent work.</td>', 'Very nice. Excellent work.', '2005-01-16 22:22:58.000000', NULL, 1),
(1112957, 133219, 7560, '<td valign="top">Puppy! Very cute shot. The bokeh here isn''t very strong though. You have a very effective shallow DOF shot. But there''s not a feeling of the OOF parts either being part of the feel of the image, or enhancing the image. That''s a critical part of what bokeh is. <br/> <br/>The little guy is still cute as a button. Congrats on your new little model. Pets are a blast to shoot.</td>', 'Puppy! Very cute shot. The bokeh here isn''t very strong though. You have a very effective shallow DOF shot. But there''s not a feeling of the OOF parts either being part of the feel of the image, or enhancing the image. That''s a critical part of what bokeh is.  The little guy is still cute as a button. Congrats on your new little model. Pets are a blast to shoot.', '2005-01-16 22:24:54.000000', NULL, 1),
(1112959, 134693, 10985, '<td valign="top">A beauty. It seems to radiate light. I would have cropped a bit more off the right side, to de-center the flower.</td>', 'A beauty. It seems to radiate light. I would have cropped a bit more off the right side, to de-center the flower.', '2005-01-16 22:25:47.000000', NULL, 1),
(1112961, 134646, 10985, '<td valign="top">Oh, indeed! Excellent and simple, yet so effective.</td>', 'Oh, indeed! Excellent and simple, yet so effective.', '2005-01-16 22:26:31.000000', NULL, 1),
(1112967, 134796, 7560, '<td valign="top">Bad bokeh on the lens, but good understanding of what it is supposed to be. :)  I love the feel of this shot.The lighting is a bit off for me. But since I''m not sure how I''d change it, I''ll  leave that alone. I love the composition here. I still have my tree up. I really need to take it down.</td>', 'Bad bokeh on the lens, but good understanding of what it is supposed to be. :)  I love the feel of this shot.The lighting is a bit off for me. But since I''m not sure how I''d change it, I''ll  leave that alone. I love the composition here. I still have my tree up. I really need to take it down.', '2005-01-16 22:28:00.000000', NULL, 1),
(1112975, 134056, 10985, '<td valign="top">This may not be, but it does looks artificially blurred. The emphasis is effectively put on the cross and buildings, but something bothers. Nicely composed.</td>', 'This may not be, but it does looks artificially blurred. The emphasis is effectively put on the cross and buildings, but something bothers. Nicely composed.', '2005-01-16 22:29:33.000000', NULL, 1),
(1112977, 134805, 10985, '<td valign="top">Cool!</td>', 'Cool!', '2005-01-16 22:30:12.000000', NULL, 1),
(1112982, 134687, 10985, '<td valign="top">Funny play on words in the title. Well done.</td>', 'Funny play on words in the title. Well done.', '2005-01-16 22:30:49.000000', NULL, 1),
(1112984, 134823, 7560, '<td valign="top">An excellent product shot. This is more about shallow DOF though than bokeh. I''d also consider cropping a bit tighter on the right. Have just the Sierra Nevada bottle showing on that side. Very well composed and lit shot.</td>', 'An excellent product shot. This is more about shallow DOF though than bokeh. I''d also consider cropping a bit tighter on the right. Have just the Sierra Nevada bottle showing on that side. Very well composed and lit shot.', '2005-01-16 22:31:26.000000', NULL, 1),
(1112985, 134775, 10985, '<td valign="top">Cool motion blur in the wings. Very nice.</td>', 'Cool motion blur in the wings. Very nice.', '2005-01-16 22:31:34.000000', NULL, 1),
(1112986, 134807, 7969, '<td valign="top">Simple, elegant, nicely composed, refreshing subject.  Speaks to me of winter.  Well done.</td>', 'Simple, elegant, nicely composed, refreshing subject.  Speaks to me of winter.  Well done.', '2005-01-16 22:31:54.000000', NULL, 1),
(1112989, 134577, 10985, '<td valign="top">Nice colors and light. Cheerful and bright!</td>', 'Nice colors and light. Cheerful and bright!', '2005-01-16 22:32:30.000000', NULL, 1),
