(1112992, 133964, 10985, '<td valign="top">Delicate and very well composed.</td>', 'Delicate and very well composed.', '2005-01-16 22:33:48.000000', NULL, 1),
(1112997, 134771, 10985, '<td valign="top">Couldn''t be blood, it''s too transparent, but the effect on the blade is very cool.</td>', 'Couldn''t be blood, it''s too transparent, but the effect on the blade is very cool.', '2005-01-16 22:34:50.000000', NULL, 1),
(1112998, 134204, 10985, '<td valign="top">Wow!</td>', 'Wow!', '2005-01-16 22:35:04.000000', NULL, 1),
