(1113003, 134758, 10985, '<td valign="top">Excellent capture!</td>', 'Excellent capture!', '2005-01-16 22:36:38.000000', NULL, 1),
(1113005, 134679, 7969, '<td valign="top">what i like about this shot is the little bits of stringy sharp bits on the top of the flower.  I really do not think the border adds much too your shot.  I also think this shot would be incredible and very dramatic with a black background, tho the blue is a creative choice and unique choice.</td>', 'what i like about this shot is the little bits of stringy sharp bits on the top of the flower.  I really do not think the border adds much too your shot.  I also think this shot would be incredible and very dramatic with a black background, tho the blue is a creative choice and unique choice.', '2005-01-16 22:37:01.000000', NULL, 1),
(1113018, 134805, 7969, '<td valign="top">Very interesting shot, I like the color tones and creativity of it.</td>', 'Very interesting shot, I like the color tones and creativity of it.', '2005-01-16 22:40:22.000000', NULL, 1),
(1113019, 134413, 10985, '<td valign="top">Beautiful ethereal light and effect. I would crop some off the left side to de-center the leaves.</td>', 'Beautiful ethereal light and effect. I would crop some off the left side to de-center the leaves.', '2005-01-16 22:40:40.000000', NULL, 1),
(1113023, 134726, 10985, '<td valign="top">Ah! Cool!</td>', 'Ah! Cool!', '2005-01-16 22:41:13.000000', NULL, 1),
