(1114037, 133891, 16148, '<td valign="top">I really like this shot.  Congratulations on 13th place.</td>', 'I really like this shot.  Congratulations on 13th place.', '2005-01-17 08:52:24.000000', NULL, 0),
(1114042, 134404, 16148, '<td valign="top">Beautiful shot!  I like the dark tones for this subject.  You should have placed higher but we''ll take any break we can get.</td>', 'Beautiful shot!  I like the dark tones for this subject.  You should have placed higher but we''ll take any break we can get.', '2005-01-17 08:56:26.000000', NULL, 0),
