INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1114049, 134704, 489, '<td valign="top">This is a wonderful image - and I am not saying that just because I love birds :-)<br/> <br/>Well composed, and great execution. Congrats on the win.</td>', 'This is a wonderful image - and I am not saying that just because I love birds :-) Well composed, and great execution. Congrats on the win.', '2005-01-17 09:01:39.000000', NULL, 0),
(1114055, 134654, 489, '<td valign="top">Great shot Skip, and a good finish in this challenge.</td>', 'Great shot Skip, and a good finish in this challenge.', '2005-01-17 09:04:49.000000', NULL, 0),
(1114077, 134588, 4517, '<td valign="top">This is outrageous, those two 1`s cost you the blue ribbon.<br/>Daylight robbery.</td>', 'This is outrageous, those two 1`s cost you the blue ribbon.Daylight robbery.', '2005-01-17 09:22:37.000000', NULL, 0),
(1114080, 134491, 14603, '<td valign="top">Judging from your Iso rating (200)the grain must have been due to the processing rather than the camera setting ?<br/>I think it works well.. adds to the "painted" look of the background.<br/> <br/>Truly beautiful image worthy of a higher placing.</td>', 'Judging from your Iso rating (200)the grain must have been due to the processing rather than the camera setting ?I think it works well.. adds to the "painted" look of the background. Truly beautiful image worthy of a higher placing.', '2005-01-17 09:24:29.000000', NULL, 0),
(1114087, 134771, 14603, '<td valign="top">One of the best overall images for me..how it didn`t make top ten has me baffled !!</td>', 'One of the best overall images for me..how it didn`t make top ten has me baffled !!', '2005-01-17 09:26:34.000000', NULL, 0),
(1114092, 134704, 18834, '<td valign="top">Excellent photo, definantly worthy of a ribbon.  Congrats.</td>', 'Excellent photo, definantly worthy of a ribbon.  Congrats.', '2005-01-17 09:29:36.000000', NULL, 0),
(1114094, 134704, 2223, '<td valign="top">Amazing shot! Congrats!!</td>', 'Amazing shot! Congrats!!', '2005-01-17 09:30:00.000000', NULL, 0),
(1114096, 134771, 2223, '<td valign="top">Thank you all for the nice comments. I''m so happy to get the score of an even 6!</td>', 'Thank you all for the nice comments. I''m so happy to get the score of an even 6!', '2005-01-17 09:33:09.000000', NULL, 0),
(1114097, 134565, 14603, '<td valign="top">A fabulous example of true bokeh<br/>You`ve got the 20d well under control I see.</td>', 'A fabulous example of true bokehYou`ve got the 20d well under control I see.', '2005-01-17 09:33:26.000000', NULL, 0),
(1114104, 134801, 17203, '<td valign="top">Ah, well... at least I held onto a 6.  I understand that this is a kid shot, and he''s not doing anything particularly interesting, but a TWO?! I would be absolutely ashamed to give anything less than a 5 to this image for Bokeh. *sigh*</td>', 'Ah, well... at least I held onto a 6.  I understand that this is a kid shot, and he''s not doing anything particularly interesting, but a TWO?! I would be absolutely ashamed to give anything less than a 5 to this image for Bokeh. *sigh*', '2005-01-17 09:36:31.000000', NULL, 0),
(1114128, 134803, 11793, '<td valign="top">boy - i didn''t think this would win, but thought it would place much higher.  i mean it''s very close up, unless it has been majorly cropped.<br/>the subtle blues in the BG are very nice.  the exposure must have been a tough one to figure - so much dark area.  add to that a fleeting subject - and you have a difficult scene to capture.<br/>i disagee with skiprow - in that in this case - being a raven - the looking out of the frame goes right along with the stereotypical feelings ravens evoke.  framing it in this way makes the viewer uneasy - as does the subject. i voted a 9...<br/> <br/>curious the lens, and distance to subject for this.<br/> <br/></td>', 'boy - i didn''t think this would win, but thought it would place much higher.  i mean it''s very close up, unless it has been majorly cropped.the subtle blues in the BG are very nice.  the exposure must have been a tough one to figure - so much dark area.  add to that a fleeting subject - and you have a difficult scene to capture.i disagee with skiprow - in that in this case - being a raven - the looking out of the frame goes right along with the stereotypical feelings ravens evoke.  framing it in this way makes the viewer uneasy - as does the subject. i voted a 9... curious the lens, and distance to subject for this. ', '2005-01-17 09:54:03.000000', NULL, 0),
(1114153, 133649, 4285, '<td valign="top">Dick,<br/> <br/>I think this was a great concept. As for noise, the 20D is frikken amazing! Great bokeh also. But I think you would have scored better if it had been something a bit more intriging seen through the glass, anything but the neighbour''s house. The reflection at the top and the drops of water on the rim took away from it also. Enough with the negatives. The blue sky against the dark gray bokeh works very well. Technically, the shot was very well taken. Hope this is helpful. :)</td>', 'Dick, I think this was a great concept. As for noise, the 20D is frikken amazing! Great bokeh also. But I think you would have scored better if it had been something a bit more intriging seen through the glass, anything but the neighbour''s house. The reflection at the top and the drops of water on the rim took away from it also. Enough with the negatives. The blue sky against the dark gray bokeh works very well. Technically, the shot was very well taken. Hope this is helpful. :)', '2005-01-17 10:20:54.000000', NULL, 0),
(1114174, 134654, 12253, '<td valign="top">Congratulations on your top 20 finish, Skip.  Great of you to provide the details pre and post.  Great shot, great crop.</td>', 'Congratulations on your top 20 finish, Skip.  Great of you to provide the details pre and post.  Great shot, great crop.', '2005-01-17 10:32:36.000000', NULL, 0),
(1114180, 134757, 24841, '<td valign="top">Focus on the lips is nice..........I love lips and this is a great portrait. Tell Poncho his lips look sweet to me :)  Glad you decided to do a different kind of portrait shot thinking outside the box!</td>', 'Focus on the lips is nice..........I love lips and this is a great portrait. Tell Poncho his lips look sweet to me :)  Glad you decided to do a different kind of portrait shot thinking outside the box!', '2005-01-17 10:34:58.000000', NULL, 0),
(1114228, 134704, 24841, '<td valign="top">Congratulations!</td>', 'Congratulations!', '2005-01-17 10:57:27.000000', NULL, 0),
(1114248, 134693, 13772, '<td valign="top">Thanks to everyone for their time to comment on my photo. I am thankful that you could see the bokeh in my photo. At least what I thought it was.</td>', 'Thanks to everyone for their time to comment on my photo. I am thankful that you could see the bokeh in my photo. At least what I thought it was.', '2005-01-17 11:07:33.000000', NULL, 0),
(1114266, 134654, 8367, '<td valign="top">I had this picked for the top three. A beautiful capture. I love the reflection.<br/>Adding: The bright red circle, imo, was too pronounced. I love all your untouched originals. They''re gorgeous!<br/><br/><i>Message edited by author 2005-01-17 11:20:48.</i></td>', 'I had this picked for the top three. A beautiful capture. I love the reflection.Adding: The bright red circle, imo, was too pronounced. I love all your untouched originals. They''re gorgeous!', '2005-01-17 11:18:47.000000', '2005-01-17 11:20:48.000000', 0),
(1114298, 134726, 23471, '<td valign="top">great shot. and congratulations on placing so well on your first entry!</td>', 'great shot. and congratulations on placing so well on your first entry!', '2005-01-17 11:32:29.000000', NULL, 0),
(1114326, 134145, 25754, '<td valign="top">Thanks for the comments everyone.<br/>Glad to know at least some of you liked it as much as I did :D</td>', 'Thanks for the comments everyone.Glad to know at least some of you liked it as much as I did :D', '2005-01-17 11:43:59.000000', NULL, 0),
(1114363, 134204, 2741, '<td valign="top">Amazing how this shot scored lower than all those "MACRO" plant, dew and berry shots.<br/> <br/>This should have been placed much higher.</td>', 'Amazing how this shot scored lower than all those "MACRO" plant, dew and berry shots. This should have been placed much higher.', '2005-01-17 11:53:57.000000', NULL, 0),
