(1114457, 134704, 8367, '<td valign="top">I thought I commented on this during the challenge.  ??<br/>I love it. Congratulations!</td>', 'I thought I commented on this during the challenge.  ??I love it. Congratulations!', '2005-01-17 12:37:58.000000', NULL, 0),
