INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2516982, 134336, 32254, '<td valign="top">Wow, very cool photo.</td>', 'Wow, very cool photo.', '2006-06-14 15:44:33.000000', NULL, 0),
(2523237, 134003, 60601, '<td valign="top">This rocks.  Composed well and the string of droplets being out of focus both in fore- and background really singles out the one drop.<br/> <br/>That said, I''d have to agree with dr_rick, cropping the left to a square, leaving the very top of the curve would definitely enhance the photo.  I''ve always loved photos that give you the impression that they continue off of the print, and leaving just the top of the curve would do that quite well.<br/> <br/>Anyway, well done!<br/> <br/><br/><br/><i>Message edited by author 2006-06-16 19:15:23.</i></td>', 'This rocks.  Composed well and the string of droplets being out of focus both in fore- and background really singles out the one drop. That said, I''d have to agree with dr_rick, cropping the left to a square, leaving the very top of the curve would definitely enhance the photo.  I''ve always loved photos that give you the impression that they continue off of the print, and leaving just the top of the curve would do that quite well. Anyway, well done! ', '2006-06-16 20:10:56.000000', '2006-06-16 20:15:23.000000', 0),
(2527455, 134758, 56539, '<td valign="top">I know that I am late with this comment on this beautiful photograph, but at the time of your submittal I had never heard of DPChallenge.  I just wanted you to know that out of ALL the photographs I saw at this site (in the challenge history) your photograph SHOULD HAVE BEEN THE BLUE RIBBON WINNER. I am surprised that you did not put prints of it up for sale!</td>', 'I know that I am late with this comment on this beautiful photograph, but at the time of your submittal I had never heard of DPChallenge.  I just wanted you to know that out of ALL the photographs I saw at this site (in the challenge history) your photograph SHOULD HAVE BEEN THE BLUE RIBBON WINNER. I am surprised that you did not put prints of it up for sale!', '2006-06-19 01:27:39.000000', NULL, 0),
(2530166, 134775, 49865, '<td valign="top">I love the elegance in this photo''s composition and color.</td>', 'I love the elegance in this photo''s composition and color.', '2006-06-19 22:25:31.000000', NULL, 0),
(2543148, 134656, 31244, '<td valign="top">Great photo!</td>', 'Great photo!', '2006-06-22 23:38:32.000000', NULL, 0),
(2821006, 134675, 36470, '<td valign="top">Incredible!  I wish I had such creativity..LOL  I would have chosen this as a ribbon winner....I guess it was close!!!</td>', 'Incredible!  I wish I had such creativity..LOL  I would have chosen this as a ribbon winner....I guess it was close!!!', '2006-09-10 19:09:23.000000', NULL, 0),
(2829244, 134810, 62642, '<td valign="top">Wow...fantastic complementation...sharpness of the plant, softness and delicateness of the snow.  I love it.</td>', 'Wow...fantastic complementation...sharpness of the plant, softness and delicateness of the snow.  I love it.', '2006-09-12 22:32:43.000000', NULL, 0),
(2850377, 134546, 52945, '<td valign="top">Amazing shot, the eyes really reach out at you from the photo.</td>', 'Amazing shot, the eyes really reach out at you from the photo.', '2006-09-20 10:04:00.000000', NULL, 0),
(2957790, 134404, 15711, '<td valign="top">This deserves a recently comment bump after all this time.  Gorgeous.  Might inspire people to do bokeh that isn''t just "circles."  LOVE the rich green and pop of yellow.</td>', 'This deserves a recently comment bump after all this time.  Gorgeous.  Might inspire people to do bokeh that isn''t just "circles."  LOVE the rich green and pop of yellow.', '2006-10-24 15:03:18.000000', NULL, 0),
(3268649, 133623, 48228, '<td valign="top">This is just a great image showing the Winter season. <br/>I also love the DOF as well.....</td>', 'This is just a great image showing the Winter season. I also love the DOF as well.....', '2007-01-22 21:50:05.000000', NULL, 0),
(3277638, 134392, 62318, '<td valign="top">An interesting idea. I think the background and the foreground mesh a bit too much. I see what you were trying to convey, just not sure about this. As far as exposure and color, it is terrific. I think placement of the locket in the lower right to see more chain might have helped. A good first attempt at Bokeh.</td>', 'An interesting idea. I think the background and the foreground mesh a bit too much. I see what you were trying to convey, just not sure about this. As far as exposure and color, it is terrific. I think placement of the locket in the lower right to see more chain might have helped. A good first attempt at Bokeh.', '2007-01-24 21:18:20.000000', NULL, 0),
(4178804, 134631, 17296, '<td valign="top">I guess I should have looked up bokah before entering! LOL oops</td>', 'I guess I should have looked up bokah before entering! LOL oops', '2007-10-18 15:21:12.000000', NULL, 0),
